}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void postLoad()
{
    next postLoad();

    CustPackingSlipJour         custPackingSlipJour;
    SalesTable              salesTable;

    select firstonly custPackingSlipJour
       where custPackingSlipJour.PackingSlipId   == this.PackingSlipId
          && custPackingSlipJour.DeliveryDate    == this.DeliveryDate;

    salesTable = SalesTable::find(custPackingSlipJour.SalesId);

    EcoResProductTranslation avaProductTranslation = EcoResProductTranslation::findByProductLanguage(InventTable::itemProduct(this.ItemId),  custPackingSlipJour.LanguageId);
    this.AVAItemName1 = avaProductTranslation.NDXProductName1;
    this.AVAItemName2 = avaProductTranslation.NDXProductName2;

    this.AVAPurchOrderNum  = salesTable.PurchOrderFormNum;
    this.AVAPurchOrderDate = salesTable.AVAEDIPurchOrderDate;

}
